const hashStr = (s) => { let h1 = 0xdeadbeef, h2 = 0x41c6ce57; for (let i = 0; i < s.length; i++) { const ch = s.charCodeAt(i); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); } h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909); h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909); return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0'); };
const cfg = $('Config').first().json;
const epic = $('Loop Epics').item.json;
const childrenResp = $('Jira GET Children').item.json;
const commentsResp = $('Jira GET Comments').item.json;
const confSearch = $('Confluence Find Page').item.json;
const fields = epic.fields || {};
const children = childrenResp.issues || [];
const comments = (commentsResp.comments || []).slice(0, 10);
const existingPages = confSearch.results || [];
const existingPage = existingPages.length > 0 ? existingPages[0] : null;

const esc = (str) => {
  if (str === null || str === undefined) return '';
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
};

const extractVal = (val) => {
  if (val === null || val === undefined) return '';
  if (Array.isArray(val)) return val.map(extractVal).filter(Boolean).join(', ');
  if (typeof val === 'object') return val.value || val.name || val.key || JSON.stringify(val);
  return String(val).trim();
};

const formatEDT = (isoStr, includeTime = true) => {
  if (!isoStr) return '';
  const d = new Date(isoStr);
  if (isNaN(d.getTime())) return String(isoStr);
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York',
    year: 'numeric',
    month: 'numeric',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true
  }).formatToParts(d);
  const getP = (t) => (parts.find(p => p.type === t) || {}).value || '';
  if (!includeTime) return `${getP('month')}/${getP('day')}/${getP('year')}`;
  const ampm = getP('dayPeriod').toLowerCase().replace('m', '');
  return `${getP('month')}/${getP('day')}/${getP('year')} ${getP('hour')}:${getP('minute')}${ampm} EDT`;
};

const BRAND_MAP = [
  { match: ['BVD', 'BOVADA'], name: 'Bovada', parentId: '277422571' },
  { match: ['OZOON'], name: 'Ozoon', parentId: '277422692' },
  { match: ['SLOTS'], name: 'Slots', parentId: '277422699' },
  { match: ['CAFE CASINO', 'CAFE'], name: 'Cafe Casino', parentId: '277422697' },
  { match: ['JOE FORTUNE', 'JFT'], name: 'Joe Fortune', parentId: '277422702' },
  { match: ['BVX'], name: 'BVX', parentId: '337289266' }
];

const rawBrand = extractVal(fields.customfield_11504).toUpperCase();
const summaryUpper = (fields.summary || '').toUpperCase();
let brandDisplay = 'All Brands';
let parentPageId = '277422705';

if (rawBrand.includes(',')) {
  brandDisplay = 'All Brands';
  parentPageId = '277422705';
} else if (rawBrand.includes('IGN')) {
  if (rawBrand.includes('AUS') || summaryUpper.includes('AUS')) {
    brandDisplay = 'Ignition AUS';
    parentPageId = '459091653';
  } else {
    brandDisplay = 'Ignition UFM';
    parentPageId = '277422694';
  }
} else {
  for (const b of BRAND_MAP) {
    if (b.match.some(m => rawBrand.includes(m))) {
      brandDisplay = b.name;
      parentPageId = b.parentId;
      break;
    }
  }
}

const promoName = extractVal(fields.customfield_10004) || (fields.summary || '').replace(/^\[.*?\]\s*/, '');
const rawStartDate = extractVal(fields.customfield_17519) || extractVal(fields.customfield_26467);
const startDateEDT = formatEDT(rawStartDate, true);
const endDateEDT = formatEDT(extractVal(fields.customfield_11221), true);
const targetAudience = extractVal(fields.customfield_25508);
const eligibility = [extractVal(fields.customfield_25544), extractVal(fields.customfield_26458)].filter(Boolean).join(' | ');

const bonuses = children.filter(c => (c.fields?.issuetype?.name || '').toLowerCase() === 'bonus');
const bonusIds = bonuses.map(b => extractVal(b.fields?.customfield_11246)).filter(Boolean);

const missingFields = [];
if (!rawBrand) missingFields.push('Brand');
if (!promoName) missingFields.push('Name of Promotion');
if (!rawStartDate) missingFields.push('Start Date');
if (!targetAudience) missingFields.push('Targeted Audience');
if (!eligibility) missingFields.push('Eligibility / Details');
if (bonuses.length > 0 && bonusIds.length === 0) missingFields.push('CM Bonus ID');

const fingerprintSource = {
  epicKey: epic.key,
  status: fields.status?.name || '',
  summary: fields.summary || '',
  promoName,
  rawBrand,
  rawStartDate,
  endDate: extractVal(fields.customfield_11221),
  targetAudience,
  eligibility,
  children: children.map(c => ({
    key: c.key,
    type: c.fields?.issuetype?.name || '',
    status: c.fields?.status?.name || '',
    summary: c.fields?.summary || '',
    updated: c.fields?.updated || '',
    bonusId: extractVal(c.fields?.customfield_11246)
  })).sort((a, b) => a.key.localeCompare(b.key)),
  commentIds: comments.map(cm => `${cm.id}:${cm.updated}`).sort()
};

const fingerprint = hashStr(JSON.stringify(fingerprintSource));
const prevFingerprint = existingPage?.metadata?.properties?.fingerprint?.value || '';

let action = 'create';
if (existingPage) {
  action = (prevFingerprint === fingerprint) ? 'noop' : 'update';
}

const titleSuffix = startDateEDT ? ` - ${startDateEDT}` : '';
const pageTitle = existingPage ? existingPage.title : `${brandDisplay} | ${promoName}${titleSuffix}`;

const calloutXhtml = missingFields.length > 0
  ? `<ac:structured-macro ac:name="warning"><ac:rich-text-body><p><strong>Incomplete MAP Data (Missing Fields):</strong> ${esc(missingFields.join(', '))}</p></ac:rich-text-body></ac:structured-macro>`
  : `<ac:structured-macro ac:name="info"><ac:rich-text-body><p><strong>Status:</strong> All required v1 fields present. Last synced: ${esc(formatEDT(new Date().toISOString(), true))}</p></ac:rich-text-body></ac:structured-macro>`;

const bonusRowsXhtml = bonuses.length === 0
  ? `<tr><td colspan="5"><em>No Bonus child tickets linked yet.</em></td></tr>`
  : bonuses.map(b => {
      const bf = b.fields || {};
      const bUrl = `${cfg.jiraBaseUrl}/browse/${b.key}`;
      const bCode = extractVal(bf.customfield_11246);
      const bPublic = extractVal(bf.customfield_26613) || bf.summary || '';
      const bType = extractVal(bf.customfield_11243);
      const bStatus = bf.status?.name || '';
      return `<tr><td><a href="${esc(bUrl)}">${esc(b.key)}</a></td><td>${esc(bPublic)}</td><td>${bCode ? `<strong>${esc(bCode)}</strong>` : ''}</td><td>${esc(bType)}</td><td>${esc(bStatus)}</td></tr>`;
    }).join('');

const childrenRowsXhtml = children.length === 0
  ? `<tr><td colspan="4"><em>No linked MAP child activities found.</em></td></tr>`
  : children.map(c => {
      const cf = c.fields || {};
      const cUrl = `${cfg.jiraBaseUrl}/browse/${c.key}`;
      return `<tr><td>${esc(cf.issuetype?.name || '')}</td><td><a href="${esc(cUrl)}">${esc(c.key)}</a></td><td>${esc(cf.summary || '')}</td><td>${esc(cf.status?.name || '')}</td></tr>`;
    }).join('');

const commentsXhtml = comments.length === 0
  ? `<p><em>No comments on Epic.</em></p>`
  : `<ul>${comments.map(cm => `<li><strong>${esc(cm.author?.displayName || 'User')}</strong> (${esc(formatEDT(cm.created, true))}): ${esc((cm.body || '').slice(0, 500))}</li>`).join('')}</ul>`;

const epicUrl = `${cfg.jiraBaseUrl}/browse/${epic.key}`;

const storageBody = `${calloutXhtml}<h2>Campaign Overview</h2><table><tbody><tr><th>Brand</th><td>${esc(brandDisplay)}</td><th>GMO / MAP Number</th><td><a href="${esc(epicUrl)}">${esc(epic.key)}</a></td></tr><tr><th>Name of Promotion</th><td>${esc(promoName)}</td><th>Epic Status</th><td>${esc(fields.status?.name || '')}</td></tr><tr><th>Start Date (EDT)</th><td>${esc(startDateEDT)}</td><th>End Date (EDT)</th><td>${esc(endDateEDT)}</td></tr><tr><th>Targeted Audience</th><td colspan="3">${esc(targetAudience)}</td></tr><tr><th>Eligibility & Details</th><td colspan="3">${esc(eligibility)}</td></tr></tbody></table><h2>Bonus Status & IDs</h2><table><thead><tr><th>Ticket</th><th>Bonus Name</th><th>CM Bonus ID</th><th>Type</th><th>Status</th></tr></thead><tbody>${bonusRowsXhtml}</tbody></table><h2>All Linked MAP Activities (${children.length})</h2><table><thead><tr><th>Type</th><th>MAP Key</th><th>Summary</th><th>Status</th></tr></thead><tbody>${childrenRowsXhtml}</tbody></table><h2>Last 10 Epic Comments</h2>${commentsXhtml}`;

return {
  json: {
    epicKey: epic.key,
    epicUrl,
    action,
    pageTitle,
    parentPageId,
    spaceKey: cfg.spaceKey,
    targetPageStatus: cfg.targetPageStatus,
    existingPageId: existingPage ? existingPage.id : null,
    existingPageVersion: existingPage ? (existingPage.version?.number || 1) : 0,
    fingerprint,
    missingFields,
    storageBody,
    mattermostWebhookUrl: cfg.mattermostWebhookUrl
  }
};
